svg.script:
//
(function () {
  var svg = document.getElementById('aug-sv');
  if (!svg) return;
  var iT = svg.querySelector('#aug-it');
  var iD = svg.querySelector('#aug-id');

  var DESCS = {
    endview:  ['End View — Shaft Ø30, Flight Ø58',
               'Cross-section shows 30 mm square shaft at centre; 58 mm outer flight diameter. Flight-to-shaft ratio governs soil displacement per revolution.'],
    dims:     ['Parametric Step Dimensions — 90.5 mm Pitch',
               'Staggered callouts mark flight leading-edge positions: 182.5, 272.5, 362.5, 452.5 mm. All driven by a single pitch parameter in the Fusion 360 model.'],
    helix:    ['Main Helix — 775 mm Overall Length',
               'Five flights over 452.5 mm active length; total shaft 775 mm including drive shank. Constant pitch ~90.5 mm per flight; right-hand helix.'],
    sideview: ['Side Projection — Compact Form',
               'Alternate orthographic projection verifies helix hand and uniform flight spacing. Useful for checking clearance between consecutive flights in assembly.'],
    isoviews: ['Isometric Variants — Parametric Model',
               'Three renders: dense-pitch (top-left), open-pitch (top-right), wide-spacing (bottom). All generated from the same Fusion 360 feature by adjusting pitch and flight-count parameters.']
  };

  function reset() {
    svg.querySelectorAll('.a-ring.lit').forEach(function (r) { r.classList.remove('lit'); });
    if (iT) iT.textContent = '';
    if (iD) iD.textContent = 'Hover the highlighted regions to explore the helix auger design';
  }

  svg.querySelectorAll('.a-feat').forEach(function (g) {
    var id   = g.dataset.id;
    var ring = g.querySelector('.a-ring');
    function on() {
      reset();
      if (ring) ring.classList.add('lit');
      var d = DESCS[id] || ['', ''];
      if (iT) iT.textContent = d[0];
      if (iD) iD.textContent = d[1];
    }
    g.addEventListener('mouseenter', on);
    g.addEventListener('click',      on);
    g.addEventListener('mouseleave', reset);
  });

  svg.addEventListener('click', function (e) {
    if (!e.target.closest('.a-feat')) reset();
  });

  if (window.matchMedia('(prefers-reduced-motion:reduce)').matches) {
    svg.querySelectorAll('.a-ring').forEach(function (r) { r.classList.add('ready'); });
    return;
  }
  svg.querySelectorAll('.a-ring').forEach(function (r, i) {
    setTimeout(function () { r.classList.add('ready'); }, 400 + i * 500);
  });
})();
//
